<?php require_once __DIR__.'/../config/auth.php';require_admin();$q=trim($_GET['q']??'');$s=db()->prepare("SELECT * FROM usuarios WHERE tipo='aluno' AND (nome LIKE ? OR email LIKE ? OR ra LIKE ?) ORDER BY nome");$s->execute(array_fill(0,3,'%'.$q.'%'));$users=$s->fetchAll();$pageTitle='Alunos';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="filterbar"><div class="searchbar"><form><input name="q" value="<?=e($q)?>" placeholder="Nome, e-mail ou RA"></form></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>RA</th><th>Telefone</th><th>Turma / Curso</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['nome'])?></b></td><td><?=e($u['email'])?></td><td><?=e($u['ra'])?></td><td><?=e($u['telefone'])?></td><td><?=e($u['turma'])?><br><small><?=e($u['curso'])?></small></td><td><span class="badge <?=$u['status']==='ativo'?'':'off'?>"><?=e($u['status'])?></span></td><td><a class="btn btn-small btn-outline" href="<?=base_url('admin/editar-aluno.php?id='.(int)$u['id'])?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
